[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ClipCast — One video is worth a thousand words</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --primary: #6366f1;
    --primary-dark: #4f46e5;
    --accent: #FF613D;
    --brand-blue: #1868DB;
    --dark: #292A2E;
    --muted: #6b7280;
    --light-bg: #f8f9ff;
    --border: #e5e7eb;
    --white: #ffffff;
    --radius: 12px;
    --radius-lg: 20px;
  }
  body { font-family: 'Inter', sans-serif; color: var(--dark); background: var(--white); line-height: 1.6; }
  a { text-decoration: none; color: inherit; }
  img { max-width: 100%; }

  /* NAV */
  nav {
    position: sticky; top: 0; z-index: 100;
    background: rgba(255,255,255,0.95); backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border);
    padding: 0 2rem;
  }
  .nav-inner {
    max-width: 1280px; margin: 0 auto;
    display: flex; align-items: center; justify-content: space-between;
    height: 64px;
  }
  .nav-logo { display: flex; align-items: center; gap: 8px; font-weight: 800; font-size: 1.25rem; color: var(--primary); }
  .nav-logo svg { width: 28px; height: 28px; }
  .nav-links { display: flex; align-items: center; gap: 2rem; }
  .nav-links a { font-size: 0.9rem; font-weight: 500; color: var(--dark); transition: color 0.15s; }
  .nav-links a:hover { color: var(--primary); }
  .nav-actions { display: flex; align-items: center; gap: 1rem; }
  .btn { display: inline-flex; align-items: center; gap: 6px; padding: 10px 20px; border-radius: 8px; font-weight: 600; font-size: 0.9rem; transition: all 0.15s; cursor: pointer; border: none; }
  .btn-ghost { background: transparent; color: var(--dark); }
  .btn-ghost:hover { background: var(--light-bg); }
  .btn-primary { background: var(--primary); color: white; }
  .btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(99,102,241,0.35); }
  .btn-accent { background: var(--accent); color: white; }
  .btn-accent:hover { background: #e5502c; transform: translateY(-1px); box-shadow: 0 4px 12px rgba(255,97,61,0.35); }
  .btn-outline { background: transparent; border: 2px solid var(--border); color: var(--dark); }
  .btn-outline:hover { border-color: var(--primary); color: var(--primary); }
  .btn-lg { padding: 14px 28px; font-size: 1rem; border-radius: 10px; }
  .btn-xl { padding: 16px 36px; font-size: 1.05rem; border-radius: 10px; }

  /* HERO */
  .hero {
    background: linear-gradient(135deg, #f0f0ff 0%, #fff8f6 50%, #f0f7ff 100%);
    padding: 100px 2rem 80px;
    text-align: center;
    position: relative; overflow: hidden;
  }
  .hero::before {
    content: ''; position: absolute; top: -200px; left: 50%; transform: translateX(-50%);
    width: 900px; height: 900px;
    background: radial-gradient(circle, rgba(99,102,241,0.08) 0%, transparent 70%);
    pointer-events: none;
  }
  .hero-badge {
    display: inline-flex; align-items: center; gap: 6px;
    background: rgba(99,102,241,0.1); color: var(--primary);
    padding: 6px 14px; border-radius: 100px; font-size: 0.8rem; font-weight: 600;
    margin-bottom: 1.5rem;
  }
  .hero h1 {
    font-size: clamp(2.5rem, 5vw, 4rem); font-weight: 900;
    line-height: 1.1; letter-spacing: -0.03em;
    max-width: 820px; margin: 0 auto 1.5rem;
    background: linear-gradient(135deg, var(--dark) 0%, var(--primary) 100%);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;
  }
  .hero p {
    font-size: 1.15rem; color: var(--muted); max-width: 580px;
    margin: 0 auto 2.5rem; line-height: 1.7;
  }
  .hero-actions { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }
  .hero-video {
    margin-top: 4rem; max-width: 900px; margin-left: auto; margin-right: auto;
    border-radius: var(--radius-lg); overflow: hidden;
    box-shadow: 0 25px 60px rgba(99,102,241,0.2), 0 8px 20px rgba(0,0,0,0.08);
    position: relative; background: var(--dark);
  }
  .hero-video-placeholder {
    width: 100%; aspect-ratio: 16/9;
    background: linear-gradient(135deg, #1a1b2e 0%, #2d2e4a 50%, #1a1b2e 100%);
    display: flex; align-items: center; justify-content: center;
    position: relative;
  }
  .play-btn {
    width: 72px; height: 72px; border-radius: 50%;
    background: rgba(255,255,255,0.15); backdrop-filter: blur(8px);
    border: 2px solid rgba(255,255,255,0.3);
    display: flex; align-items: center; justify-content: center;
    cursor: pointer; transition: all 0.2s;
  }
  .play-btn:hover { background: rgba(255,255,255,0.25); transform: scale(1.05); }
  .play-btn svg { width: 28px; height: 28px; color: white; margin-left: 4px; }
  .recording-ui {
    position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%);
    background: rgba(0,0,0,0.7); backdrop-filter: blur(8px);
    border: 1px solid rgba(255,255,255,0.15); border-radius: 100px;
    padding: 8px 20px; display: flex; align-items: center; gap: 12px;
  }
  .rec-dot { width: 8px; height: 8px; border-radius: 50%; background: #ef4444; animation: pulse-rec 1.5s infinite; }
  @keyframes pulse-rec { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }
  .rec-text { color: white; font-size: 0.8rem; font-weight: 500; }
  .rec-time { color: #9ca3af; font-size: 0.8rem; }

  /* LOGO BAR */
  .logo-bar {
    padding: 3rem 2rem;
    border-bottom: 1px solid var(--border);
    text-align: center;
  }
  .logo-bar p { color: var(--muted); font-size: 0.85rem; font-weight: 500; margin-bottom: 2rem; letter-spacing: 0.05em; text-transform: uppercase; }
  .logos { display: flex; align-items: center; justify-content: center; gap: 3rem; flex-wrap: wrap; }
  .logo-item { font-size: 1.1rem; font-weight: 700; color: #9ca3af; letter-spacing: -0.02em; }

  /* SECTIONS */
  .section { padding: 80px 2rem; }
  .section-alt { background: var(--light-bg); }
  .container { max-width: 1280px; margin: 0 auto; }
  .section-label {
    display: inline-flex; align-items: center; gap: 6px;
    background: rgba(99,102,241,0.1); color: var(--primary);
    padding: 5px 12px; border-radius: 100px; font-size: 0.78rem; font-weight: 700;
    margin-bottom: 1rem; letter-spacing: 0.05em; text-transform: uppercase;
  }
  .section-label.orange { background: rgba(255,97,61,0.1); color: var(--accent); }
  .section-label.green { background: rgba(16,185,129,0.1); color: #10b981; }
  h2.section-title {
    font-size: clamp(1.8rem, 3.5vw, 2.8rem); font-weight: 800;
    line-height: 1.15; letter-spacing: -0.02em;
    margin-bottom: 1rem;
  }
  .section-subtitle { font-size: 1.05rem; color: var(--muted); max-width: 580px; line-height: 1.7; }
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
  .two-col.reverse { direction: rtl; }
  .two-col.reverse > * { direction: ltr; }

  /* FEATURE HIGHLIGHT */
  .feature-visual {
    border-radius: var(--radius-lg); overflow: hidden;
    box-shadow: 0 20px 50px rgba(99,102,241,0.15);
    background: linear-gradient(135deg, #1a1b2e, #2d2e4a);
    aspect-ratio: 4/3; display: flex; align-items: center; justify-content: center;
    position: relative;
  }
  .feature-visual-inner {
    width: 85%; background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: var(--radius); padding: 1.5rem;
  }
  .fake-browser { background: rgba(0,0,0,0.4); border-radius: 8px; overflow: hidden; }
  .fake-browser-bar { background: rgba(255,255,255,0.08); padding: 8px 12px; display: flex; align-items: center; gap: 6px; }
  .dot { width: 10px; height: 10px; border-radius: 50%; }
  .dot-r { background: #ef4444; } .dot-y { background: #f59e0b; } .dot-g { background: #10b981; }
  .fake-browser-content { padding: 1rem; min-height: 120px; }
  .bug-card { background: rgba(255,255,255,0.08); border-radius: 8px; padding: 1rem; margin-bottom: 0.5rem; }
  .bug-title { color: rgba(255,255,255,0.9); font-size: 0.8rem; font-weight: 600; margin-bottom: 0.25rem; }
  .bug-meta { color: rgba(255,255,255,0.4); font-size: 0.7rem; }
  .ai-badge { display: inline-block; background: linear-gradient(90deg, #6366f1, #8b5cf6); color: white; font-size: 0.65rem; font-weight: 700; padding: 2px 8px; border-radius: 100px; margin-top: 0.5rem; }

  /* FEATURES LIST */
  .features-list { list-style: none; }
  .features-list li {
    display: flex; gap: 1rem; align-items: flex-start;
    padding: 1.25rem 0; border-bottom: 1px solid var(--border);
  }
  .features-list li:last-child { border-bottom: none; }
  .feature-icon {
    width: 40px; height: 40px; border-radius: 10px;
    background: rgba(99,102,241,0.1); display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
  }
  .feature-icon svg { width: 18px; height: 18px; color: var(--primary); }
  .feature-icon.orange { background: rgba(255,97,61,0.1); }
  .feature-icon.orange svg { color: var(--accent); }
  .feature-text h4 { font-size: 0.95rem; font-weight: 700; margin-bottom: 0.25rem; }
  .feature-text p { font-size: 0.88rem; color: var(--muted); }

  /* INTEGRATIONS */
  .integrations-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 1rem; }
  .integration-card {
    background: white; border: 1px solid var(--border); border-radius: var(--radius);
    padding: 1.25rem; display: flex; align-items: center; justify-content: center;
    font-weight: 600; font-size: 0.8rem; color: var(--muted);
    transition: all 0.2s; cursor: default;
    flex-direction: column; gap: 6px;
  }
  .integration-card:hover { border-color: var(--primary); color: var(--primary); transform: translateY(-2px); box-shadow: 0 4px 12px rgba(99,102,241,0.1); }
  .integration-icon { width: 32px; height: 32px; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 1.2rem; }

  /* USE CASES */
  .use-cases-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.5rem; }
  .use-case-card {
    background: white; border: 1px solid var(--border); border-radius: var(--radius-lg);
    padding: 2rem; transition: all 0.2s;
  }
  .use-case-card:hover { border-color: var(--primary); box-shadow: 0 8px 24px rgba(99,102,241,0.1); transform: translateY(-2px); }
  .use-case-icon { width: 48px; height: 48px; border-radius: 12px; display: flex; align-items: center; justify-content: center; margin-bottom: 1rem; }
  .use-case-card h3 { font-size: 1.1rem; font-weight: 700; margin-bottom: 0.5rem; }
  .use-case-card p { font-size: 0.9rem; color: var(--muted); }

  /* FEATURES GRID */
  .features-grid-8 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
  .feature-grid-item {
    background: white; border: 1px solid var(--border); border-radius: var(--radius);
    padding: 1.5rem; display: flex; align-items: flex-start; gap: 0.75rem;
    transition: all 0.2s;
  }
  .feature-grid-item:hover { border-color: var(--primary); box-shadow: 0 4px 12px rgba(99,102,241,0.08); }
  .feature-grid-item svg { width: 20px; height: 20px; color: var(--primary); flex-shrink: 0; margin-top: 2px; }
  .feature-grid-item span { font-size: 0.9rem; font-weight: 600; }

  /* SECURITY */
  .security-items { list-style: none; }
  .security-items li {
    display: flex; gap: 0.75rem; align-items: flex-start;
    padding: 0.75rem 0;
  }
  .security-items li svg { width: 18px; height: 18px; color: #10b981; flex-shrink: 0; margin-top: 2px; }
  .security-items li span { font-size: 0.95rem; }
  .security-badges { display: flex; gap: 0.75rem; flex-wrap: wrap; margin-top: 1.5rem; }
  .security-badge {
    border: 1px solid var(--border); border-radius: 8px; padding: 8px 14px;
    font-size: 0.8rem; font-weight: 600; color: var(--muted);
  }

  /* TESTIMONIALS */
  .testimonials-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
  .testimonial-card {
    background: white; border: 1px solid var(--border); border-radius: var(--radius-lg);
    padding: 1.75rem; position: relative;
  }
  .testimonial-card::before { content: '"'; position: absolute; top: 1rem; right: 1.25rem; font-size: 3rem; color: var(--primary); opacity: 0.15; font-family: Georgia; line-height: 1; }
  .testimonial-stars { color: #f59e0b; margin-bottom: 1rem; font-size: 0.9rem; }
  .testimonial-card p { font-size: 0.9rem; color: var(--dark); line-height: 1.65; margin-bottom: 1.25rem; }
  .testimonial-author { display: flex; align-items: center; gap: 0.75rem; }
  .avatar { width: 40px; height: 40px; border-radius: 50%; font-weight: 700; font-size: 0.85rem; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
  .testimonial-author .name { font-size: 0.88rem; font-weight: 700; }
  .testimonial-author .title { font-size: 0.78rem; color: var(--muted); }

  /* BLOG */
  .blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.5rem; }
  .blog-card {
    background: white; border: 1px solid var(--border); border-radius: var(--radius-lg);
    overflow: hidden; transition: all 0.2s;
  }
  .blog-card:hover { box-shadow: 0 8px 24px rgba(0,0,0,0.08); transform: translateY(-2px); }
  .blog-card-img { aspect-ratio: 16/9; background: linear-gradient(135deg, #e0e7ff, #c7d2fe); display: flex; align-items: center; justify-content: center; }
  .blog-card-body { padding: 1.5rem; }
  .blog-tag { font-size: 0.75rem; font-weight: 700; color: var(--primary); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 0.5rem; }
  .blog-card h3 { font-size: 1rem; font-weight: 700; line-height: 1.4; margin-bottom: 0.5rem; }
  .blog-card p { font-size: 0.85rem; color: var(--muted); }

  /* ENTERPRISE CTA */
  .enterprise-cta {
    background: linear-gradient(135deg, #1a1b2e, #2d1b69);
    border-radius: var(--radius-lg); padding: 3rem; display: flex;
    align-items: center; justify-content: space-between; gap: 2rem;
  }
  .enterprise-cta h2 { color: white; font-size: 1.6rem; font-weight: 800; margin-bottom: 0.5rem; }
  .enterprise-cta p { color: rgba(255,255,255,0.6); font-size: 0.95rem; }

  /* CTA BANNER */
  .cta-banner {
    background: linear-gradient(135deg, var(--primary) 0%, #8b5cf6 100%);
    padding: 80px 2rem; text-align: center;
  }
  .cta-banner h2 { font-size: clamp(2rem, 4vw, 3rem); font-weight: 900; color: white; margin-bottom: 1rem; }
  .cta-banner p { color: rgba(255,255,255,0.75); font-size: 1rem; margin-bottom: 2rem; }

  /* FOOTER */
  footer { background: var(--dark); color: white; padding: 4rem 2rem 2rem; }
  .footer-grid { display: grid; grid-template-columns: 2fr repeat(5, 1fr); gap: 2rem; margin-bottom: 3rem; }
  .footer-brand p { color: rgba(255,255,255,0.5); font-size: 0.85rem; margin-top: 0.75rem; max-width: 200px; }
  .footer-col h4 { font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: rgba(255,255,255,0.4); margin-bottom: 1rem; }
  .footer-col ul { list-style: none; }
  .footer-col ul li { margin-bottom: 0.5rem; }
  .footer-col ul li a { color: rgba(255,255,255,0.6); font-size: 0.85rem; transition: color 0.15s; }
  .footer-col ul li a:hover { color: white; }
  .footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 2rem; display: flex; justify-content: space-between; align-items: center; }
  .footer-bottom p { color: rgba(255,255,255,0.4); font-size: 0.8rem; }
  .footer-bottom-links { display: flex; gap: 1.5rem; }
  .footer-bottom-links a { color: rgba(255,255,255,0.4); font-size: 0.8rem; }
  .footer-bottom-links a:hover { color: white; }

  /* COOKIE BANNER */
  #cookie-banner {
    position: fixed; bottom: 1.5rem; left: 50%; transform: translateX(-50%);
    background: white; border: 1px solid var(--border);
    border-radius: var(--radius-lg); padding: 1.5rem 2rem;
    box-shadow: 0 20px 60px rgba(0,0,0,0.15);
    max-width: 680px; width: calc(100% - 2rem);
    z-index: 999; display: flex; align-items: center; gap: 1.5rem;
  }
  .cookie-text p { font-size: 0.88rem; color: var(--muted); }
  .cookie-text strong { color: var(--dark); }
  .cookie-actions { display: flex; gap: 0.75rem; flex-shrink: 0; flex-wrap: wrap; }
  .cookie-actions .btn { padding: 8px 16px; font-size: 0.82rem; }

  /* MODAL */
  #cookie-modal {
    position: fixed; inset: 0; z-index: 1000;
    background: rgba(0,0,0,0.5); display: none;
    align-items: center; justify-content: center; padding: 1rem;
  }
  #cookie-modal.open { display: flex; }
  .modal-box { background: white; border-radius: var(--radius-lg); padding: 2rem; max-width: 500px; width: 100%; }
  .modal-box h3 { font-size: 1.2rem; font-weight: 800; margin-bottom: 0.5rem; }
  .modal-box > p { font-size: 0.9rem; color: var(--muted); margin-bottom: 1.5rem; }
  .cookie-category {
    display: flex; justify-content: space-between; align-items: flex-start;
    padding: 1rem 0; border-bottom: 1px solid var(--border);
  }
  .cookie-category:last-of-type { border-bottom: none; }
  .cookie-category h4 { font-size: 0.9rem; font-weight: 700; }
  .cookie-category p { font-size: 0.8rem; color: var(--muted); max-width: 300px; }
  .toggle-switch { position: relative; width: 44px; height: 24px; flex-shrink: 0; }
  .toggle-switch input { opacity: 0; width: 0; height: 0; }
  .toggle-slider {
    position: absolute; cursor: pointer; inset: 0;
    background: #d1d5db; border-radius: 100px; transition: 0.2s;
  }
  .toggle-slider::before {
    content: ''; position: absolute; width: 18px; height: 18px;
    border-radius: 50%; background: white; left: 3px; top: 3px; transition: 0.2s;
  }
  .toggle-switch input:checked + .toggle-slider { background: var(--primary); }
  .toggle-switch input:checked + .toggle-slider::before { transform: translateX(20px); }
  .modal-actions { display: flex; justify-content: flex-end; gap: 0.75rem; margin-top: 1.5rem; }

  /* RESPONSIVE */
  @media (max-width: 1024px) {
    .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
    .integrations-grid { grid-template-columns: repeat(3, 1fr); }
    .features-grid-8 { grid-template-columns: repeat(2, 1fr); }
  }
  @media (max-width: 768px) {
    .nav-links { display: none; }
    .two-col { grid-template-columns: 1fr; gap: 2rem; }
    .two-col.reverse { direction: ltr; }
    .use-cases-grid { grid-template-columns: 1fr; }
    .testimonials-grid { grid-template-columns: 1fr; }
    .blog-grid { grid-template-columns: 1fr; }
    .footer-grid { grid-template-columns: 1fr 1fr; }
    .enterprise-cta { flex-direction: column; text-align: center; }
    #cookie-banner { flex-direction: column; }
  }
</style>
</head>
<body>

<!-- NAV -->
<nav>
  <div class="nav-inner">
    <a href="index.html" class="nav-logo">
      <svg viewBox="0 0 28 28" fill="none" xmlns="http://www.w3.org/2000/svg">
        <rect width="28" height="28" rx="8" fill="#6366f1"/>
        <path d="M8 14a6 6 0 0 1 6-6v12a6 6 0 0 1-6-6Z" fill="white"/>
        <circle cx="18" cy="14" r="4" fill="#FF613D"/>
        <circle cx="18" cy="14" r="2" fill="white" opacity="0.8"/>
      </svg>
      ClipCast
    </a>
    <div class="nav-links">
      <a href="index.html">Product</a>
      <a href="enterprise.html">Enterprise</a>
      <a href="pricing.html">Pricing</a>
      <a href="#">Solutions</a>
      <a href="#">Resources</a>
    </div>
    <div class="nav-actions">
      <a href="login.html" class="btn btn-ghost">Sign In</a>
      <a href="signup.html" class="btn btn-primary">Get Started for free</a>
    </div>
  </div>
</nav>

<!-- HERO -->
<section class="hero">
  <div class="hero-badge">
    <svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor"><circle cx="6" cy="6" r="6"/></svg>
    Now with AI-powered video editing
  </div>
  <h1>One video is worth a thousand words</h1>
  <p>Easily record and share AI-powered video messages with your teammates and customers to supercharge productivity.</p>
  <div class="hero-actions">
    <a href="signup.html" class="btn btn-primary btn-xl">Get ClipCast for free</a>
    <button class="btn btn-outline btn-xl">
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
      Install Chrome Extension
    </button>
  </div>
  <div class="hero-video">
    <div class="hero-video-placeholder">
